@props([
    'paginator' => null,
])

@php
    use Illuminate\Contracts\Pagination\LengthAwarePaginator;

    $hasPaginator = $paginator instanceof LengthAwarePaginator;
@endphp

<nav {{
    $attributes->class([
        'pagination',
        'mx-auto flex w-full justify-center',
    ])->merge([
        'role' => 'navigation',
        'aria-label' => 'pagination',
        'data-pagination' => true,
    ])
}}>
    @if ($hasPaginator)
        <x-ui::pagination.content>
            <x-ui::pagination.item>
                <x-ui::pagination.previous
                    :href="$paginator->previousPageUrl() ?? '#'"
                    :disabled="$paginator->onFirstPage()"
                />
            </x-ui::pagination.item>

            @foreach ($paginator->getUrlRange(max(1, $paginator->currentPage() - 1), min($paginator->lastPage(), $paginator->currentPage() + 1)) as $page => $url)
                <x-ui::pagination.item>
                    <x-ui::pagination.link :href="$url" :is-active="$page === $paginator->currentPage()">
                        {{ $page }}
                    </x-ui::pagination.link>
                </x-ui::pagination.item>
            @endforeach

            <x-ui::pagination.item>
                <x-ui::pagination.next
                    :href="$paginator->nextPageUrl() ?? '#'"
                    :disabled="! $paginator->hasMorePages()"
                />
            </x-ui::pagination.item>
        </x-ui::pagination.content>
    @else
        {{ $slot }}
    @endif
</nav>

@props([
    'href' => '#',
    'isActive' => false,
    'disabled' => false,
])

@php
    $isDisabled = (bool) $disabled;
    $tag = $isDisabled ? 'span' : 'a';
@endphp

<{{ $tag }}
    {{
        $attributes->class([
            'pagination__link',
            'inline-flex size-9 items-center justify-center rounded-md text-sm font-medium transition-colors',
            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-950/10 dark:focus-visible:ring-zinc-300/20',
            $isActive
            ? 'border border-zinc-200 bg-white text-zinc-950 shadow-sm dark:border-zinc-700 dark:bg-zinc-950 dark:text-zinc-50'
            : 'text-zinc-600 hover:bg-zinc-100 hover:text-zinc-950 dark:text-zinc-400 dark:hover:bg-zinc-800 dark:hover:text-zinc-50',
            $isDisabled ? 'pointer-events-none opacity-50' : null,
        ])->merge([
            'href' => $isDisabled ? null : $href,
            'aria-current' => $isActive ? 'page' : null,
            'aria-disabled' => $isDisabled ? 'true' : null,
            'data-pagination-link' => true,
            'data-active' => $isActive ? 'true' : null,
        ])
    }}
>
    {{ $slot }}
</{{ $tag }}>
